-- Editorial baseline. Source facts were checked against the linked public reference.
-- Add a new revision and switch its aliases together when a published lesson changes.
CREATE TABLE finwiz_knowledge_edition (
    slug varchar(64) NOT NULL CHECK (slug ~ '^[a-z0-9-]+$'),
    revision integer NOT NULL CHECK (revision > 0),
    title varchar(120) NOT NULL,
    source_label varchar(160) NOT NULL,
    source_url varchar(512) NOT NULL CHECK (source_url LIKE 'https://%'),
    reviewed_on date NOT NULL,
    review_status varchar(16) NOT NULL CHECK (review_status IN ('SOURCE_CHECKED', 'WITHDRAWN')),
    basic_answer text NOT NULL,
    expanded_addendum text NOT NULL,
    full_addendum text NOT NULL,
    PRIMARY KEY (slug, revision)
);

CREATE TABLE finwiz_knowledge_alias (
    phrase varchar(180) PRIMARY KEY,
    slug varchar(64) NOT NULL,
    revision integer NOT NULL,
    FOREIGN KEY (slug, revision) REFERENCES finwiz_knowledge_edition(slug, revision)
);

WITH seed(slug, title, source_label, source_url, basic_answer, expanded_addendum, full_addendum, aliases) AS (VALUES
    ('financial-statements', 'Financial statements', 'SEC Beginners’ Guide to Financial Statements', 'https://www.sec.gov/about/reports-publications/beginners-guide-financial-statements', 'A balance sheet shows assets, liabilities and equity at a date. An income statement shows revenue, expenses and profit over a period. A cash flow statement explains changes in cash from operating, investing and financing activities.', 'A company can record a credit sale as revenue before the customer pays. Profit can rise while cash collections lag. Compare statements for the same reporting period and read the notes for material accounting policies.', 'Trace a credit sale through profit, accounts receivable and cash. Then compare reported profit with operating cash flow across several periods. A single quarter may reflect seasonal collections rather than a lasting pattern.', ARRAY['what are financial statements', 'explain financial statements', 'teach me the three financial statements', 'explain a company''s financial statements']),
    ('cash-flow', 'Cash flow', 'SEC Beginners’ Guide to Financial Statements', 'https://www.sec.gov/about/reports-publications/beginners-guide-financial-statements', 'Cash flow measures cash entering and leaving a business. Operating cash flow tracks cash from its operations. Investing cash flow includes items such as equipment purchases, and financing cash flow includes borrowing and repayments.', 'If a business bills 100 but collects 70, the sale and the cash receipt are different events. Compare operating cash flow with net income, and check changes in receivables and inventory.', 'Compare operating cash flow over multiple periods. Look for changes driven by working capital, such as slower collections or delayed supplier payments, before treating a one-period increase as sustainable.', ARRAY['what is cash flow', 'explain cash flow', 'what is operating cash flow', 'explain operating cash flow']),
    ('free-cash-flow', 'Free cash flow', 'SEC Beginners’ Guide to Financial Statements', 'https://www.sec.gov/about/reports-publications/beginners-guide-financial-statements', 'One common definition of free cash flow is operating cash flow minus capital expenditures. If operating cash flow is 100 and capital spending is 30, this measure is 70 in the same currency.', 'Capital expenditures appear in investing cash flows. Check how the company defines free cash flow and whether it adjusts for items such as leases or acquisitions before comparing companies.', 'A temporary cut in capital spending can raise free cash flow today while increasing maintenance needs later. In the example, raising capital spending from 30 to 50 reduces free cash flow from 70 to 50 if operating cash flow stays at 100.', ARRAY['what is free cash flow', 'how is free cash flow calculated', 'explain free cash flow']),
    ('balance-sheet', 'Balance sheet', 'SEC Beginners’ Guide to Financial Statements', 'https://www.sec.gov/about/reports-publications/beginners-guide-financial-statements', 'A balance sheet reports what a company owns and owes at a specified date. Assets equal liabilities plus shareholders’ equity. With assets of 100 and liabilities of 60, equity is 40 in the same currency.', 'Balance-sheet amounts reflect accounting measurements. They can differ from what the company could collect by selling the assets. Check how soon liabilities fall due and how readily assets can be converted to cash.', 'Compare maturity dates and the composition of current assets. Inventory and overdue receivables can be less liquid than cash, even when their carrying values make a liquidity ratio look comfortable.', ARRAY['what is a balance sheet', 'explain a balance sheet', 'explain the balance sheet']),
    ('income-statement', 'Income statement', 'SEC Beginners’ Guide to Financial Statements', 'https://www.sec.gov/about/reports-publications/beginners-guide-financial-statements', 'An income statement summarizes revenue and expenses over a period. Net income is the amount left after recognized expenses, taxes and other relevant items.', 'If revenue is 100 and recognized expenses including tax total 85, net income is 15 in the same currency. Review whether unusual gains or expenses materially affected that result.', 'Compare operating margin and net margin across periods. A change in interest expense or taxes can move net margin even when underlying operating performance stays similar.', ARRAY['what is an income statement', 'explain the income statement', 'what is a profit and loss statement']),
    ('price-earnings', 'Price-to-earnings ratio', 'SEC Investor.gov P/E glossary', 'https://www.investor.gov/introduction-investing/investing-basics/glossary/price-earnings-pe-ratio', 'The price-to-earnings ratio divides share price by earnings per share. A price of 120 and earnings per share of 10 give 12×. A negative or unusually small earnings figure can make the ratio uninformative.', 'Use the same reporting basis when comparing companies. A trailing ratio uses reported earnings and a forward ratio uses estimates. Differences in growth, risk and accounting can explain different multiples.', 'With price held at 120, earnings of 8 per share imply 15× while earnings of 12 imply 10×. Try comparing two companies using normalized earnings before drawing a valuation conclusion.', ARRAY['what is p/e', 'what is pe ratio', 'what is the p/e ratio', 'what is a price to earnings ratio', 'explain p/e', 'explain the p/e ratio', 'what is price to earnings', 'when can a low p/e ratio be misleading']),
    ('etf', 'Exchange-traded fund', 'SEC Investor.gov ETF bulletin', 'https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/characteristics-mutual-funds-exchange-traded-funds', 'An ETF pools money to hold a portfolio and its shares trade on an exchange. An individual stock represents a stake in one company. The diversification an ETF provides depends on what it holds.', 'Compare the ETF’s holdings, fees and bid–ask spread. Its exchange price can differ from the per-share value of its underlying assets. A narrowly focused fund may still carry concentrated risk.', 'For a paper exercise, compare a broad-market ETF with a sector ETF using their largest holdings and costs. Consider how a sector shock could affect each differently.', ARRAY['what is an etf', 'what are etfs', 'explain etfs', 'what is an exchange traded fund', 'what is the difference between stocks and etfs']),
    ('diversification', 'Diversification', 'SEC Investor.gov Asset Allocation and Diversification', 'https://www.investor.gov/introduction-investing/getting-started/asset-allocation', 'Diversification spreads exposure across holdings and sources of risk. Owning several companies in one industry can leave a portfolio exposed to the same industry downturn.', 'If ten holdings each rely on a similar market or industry, the number of positions can overstate diversification. Inspect sector weights and the largest positions as well as the count.', 'Compare exposure to common drivers such as interest rates, commodity prices and customer markets. Relationships between investments can shift, especially when financial conditions change.', ARRAY['what is diversification', 'how does diversification work', 'explain diversification', 'what is concentration risk', 'how do i identify concentration risk', 'why can a portfolio have many holdings and still be concentrated']),
    ('limit-order', 'Limit order', 'SEC Investor.gov Types of Orders', 'https://www.investor.gov/introduction-investing/investing-basics/how-stock-markets-work/types-orders', 'A limit order sets the highest price a buyer will accept or the lowest price a seller will accept. A buy limit at 100 can execute at 100 or below if matching liquidity is available.', 'A limit order controls the permitted price. It can remain completely or partly unfilled when price or queue conditions prevent execution.', 'In paper trading, compare a passive buy limit with a more aggressive limit. Record how changing the limit affects both execution likelihood and the maximum paid price.', ARRAY['what is a limit order', 'how does a limit order work', 'explain limit orders']),
    ('market-order', 'Market order', 'SEC Investor.gov Types of Orders', 'https://www.investor.gov/introduction-investing/investing-basics/how-stock-markets-work/types-orders', 'A market order seeks immediate execution at available prices. The last reported trade can differ from the price available when the order arrives.', 'In a thin order book, a larger order can execute across multiple prices. The spread is the difference between the best advertised bid and ask.', 'In a paper exercise, compare the observed execution price with the quote before submitting an order. Separate the spread from further price movement and compare with a limit order.', ARRAY['what is a market order', 'how does a market order work', 'explain market orders']),
    ('futures', 'Futures contracts', 'SEC Investor.gov Futures contract', 'https://www.investor.gov/introduction-investing/investing-basics/glossary/futures-contract', 'A futures contract creates an obligation tied to a specified asset, amount and future date under its contract terms. Long and short positions can both lose money.', 'Margin is collateral and can be much smaller than the economic exposure. A price move can create losses larger than the amount initially posted, and contracts can have different settlement rules.', 'In paper trading, multiply the price change by the contract multiplier to estimate the position’s change before costs. Read the contract’s expiry and settlement terms before comparing markets.', ARRAY['what is a futures contract', 'what are futures', 'explain futures contracts']),
    ('options', 'Options contracts', 'SEC Investor.gov Options glossary', 'https://www.investor.gov/introduction-investing/investing-basics/glossary/options', 'A call gives its buyer the right to buy and a put gives its buyer the right to sell at a strike price under the contract terms. The buyer pays a premium. The seller takes on the corresponding obligation.', 'At expiry, a call with strike 100 and underlying price 110 has 10 of intrinsic value per unit. A premium of 4 leaves 6 per unit before fees in this simplified example.', 'Compare the buyer’s payoff at prices below, at and above the strike. Contract multiplier, exercise style and settlement can change the practical consequences. The example describes expiry payoff.', ARRAY['what is an option', 'what are options', 'explain options contracts', 'what is a call option', 'what is a put option']),
    ('compounding', 'Compounding', 'SEC Investor.gov Introduction to Investing', 'https://www.investor.gov/introduction-investing', 'Compounding occurs when earnings remain invested and can earn further returns. A starting value of 100 that rises 10% twice becomes 121 if there are no cash flows or costs.', 'Multiplying 100 × 1.10 × 1.10 gives 121. That reflects a total change of 21%, because the second increase applies to 110.', 'Compare 100 × 1.20 × 0.80 with 100. The result is 96, showing why equal percentage gains and losses do not cancel when applied to different bases.', ARRAY['what is compounding', 'what is compound interest', 'how does compounding work']),
    ('return', 'Investment return', 'SEC Investor.gov Introduction to Investing', 'https://www.investor.gov/introduction-investing', 'A return measures investment gain or loss relative to the starting investment. Simple price return = (ending price − starting price) ÷ starting price × 100. Total return also accounts for distributions such as dividends.', 'From 100 to 110, the price return is 10%. If you also receive 2 in dividends under a simple holding-period illustration, the return including them is 12% before fees and tax.', 'Deposits and withdrawals complicate portfolio performance comparisons. For a paper exercise, track contributions separately from trade gains and compare with a benchmark over the same period.', ARRAY['what is an investment return', 'what is total return', 'what is a stock return', 'how is simple return calculated']),
    ('expense-ratio', 'Expense ratio', 'SEC Investor.gov Expense ratio', 'https://www.investor.gov/introduction-investing/investing-basics/glossary/expense-ratio', 'A fund’s expense ratio is its annual operating expense expressed as a percentage of assets. It reduces the fund’s returns through ongoing expenses.', 'At a 0.5% annual expense ratio, 10,000 held for one year corresponds to roughly 50 in operating expenses if the value stays constant. Actual cost varies with asset value.', 'Compare total implementation cost as well as the expense ratio. Bid–ask spreads, commissions and taxes can matter when trading or holding a fund.', ARRAY['what is an expense ratio', 'explain expense ratio', 'what is the expense ratio']),
    ('moving-average', 'Simple moving average', 'Fidelity Simple Moving Average guide', 'https://www.fidelity.com/learning-center/trading-investing/technical-analysis/technical-indicator-guide/sma', 'A simple moving average is the mean of recent observations. A three-session average of closes 10, 12 and 14 is 12.', 'The window moves forward after each observation. With a new close of 16, the next three-session mean becomes 14.', 'A longer window generally smooths more of the variation and reacts more slowly. Compare two windows in paper research and identify where a sideways market produces misleading signals.', ARRAY['what is a simple moving average', 'what is sma', 'explain moving averages', 'what do sma 20 and sma 50 describe']),
    ('consumer-price-index', 'Consumer price index', 'U.S. Bureau of Labor Statistics CPI FAQ', 'https://www.bls.gov/cpi/questions-and-answers.htm', 'A consumer price index tracks average price change for a representative basket of consumer goods and services. A higher index means the measured basket cost more than in the comparison period.', 'If an index rises from 120 to 126 over a year, the change is (126 − 120) ÷ 120 × 100 = 5%. Use the same CPI series for both dates.', 'Different baskets and methods make CPI series across countries difficult to compare directly. Check the reference period and whether the series has been seasonally adjusted.', ARRAY['what is cpi', 'what is the consumer price index', 'explain cpi'])
), editions AS (
    INSERT INTO finwiz_knowledge_edition
        (slug, revision, title, source_label, source_url, reviewed_on, review_status, basic_answer, expanded_addendum, full_addendum)
    SELECT slug, 1, title, source_label, source_url, DATE '2026-11-28', 'SOURCE_CHECKED', basic_answer, expanded_addendum, full_addendum
    FROM seed
    RETURNING slug, revision
)
INSERT INTO finwiz_knowledge_alias(phrase, slug, revision)
SELECT alias.phrase, editions.slug, editions.revision
FROM editions JOIN seed USING (slug) CROSS JOIN LATERAL unnest(seed.aliases) AS alias(phrase);
